struct BIT {
    int n; vector<long long> t;
    BIT(int n) : n(n), t(n + 1, 0) {}
    void add(int i, long long v) {            // a[i] += v
        for (; i <= n; i += i & -i) t[i] += v;
    }
    long long sum(int i) {                    // a[1..i]
        long long s = 0;
        for (; i > 0; i -= i & -i) s += t[i];
        return s;
    }
    long long range(int l, int r) { return sum(r) - sum(l - 1); }
};

struct Seg {
    int n; vector<long long> t;
    Seg(int n) : n(n), t(2 * n, 0) {}
    void set(int i, long long v) {            // a[i] = v, 0-indexed
        for (t[i += n] = v; i > 1; i >>= 1) t[i >> 1] = t[i] + t[i ^ 1];
    }
    long long query(int l, int r) {           // sum of [l, r)
        long long s = 0;
        for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
            if (l & 1) s += t[l++];
            if (r & 1) s += t[--r];
        }
        return s;
    }
};
